import { AndroidPermission, ManifestPermission, ManifestPermissionGroup } from '@droid/android';
import { useProxyWatchUpdates, useTranslation } from '@fanfanlo';
import CloseIcon from '@mui/icons-material/Close';
import { Box, Chip, Dialog, DialogContent, DialogTitle, Divider, IconButton, Stack, Typography } from '@mui/material';
import { useMemo } from 'react';
import { AndroidPermissionsCheckbox } from './AndroidPermissionsCheckbox';

// 日志前缀
const LOG_PREFIX = '[AndroidPermissionsPopup]';

interface IPermissionsProps {
  permissions: AndroidPermission[];
}

interface AndroidPermissionsPopupProps {
  open: boolean; // 是否打开弹窗
  onClose: () => void; // 关闭弹窗的回调
  permissionsProps: IPermissionsProps; // 权限数据对象
}

/**
 * 权限选择器弹窗组件
 */
export const AndroidPermissionsPopup: React.FC<AndroidPermissionsPopupProps> = ({
  open,
  onClose,
  permissionsProps
}) => {
  console.log(`${LOG_PREFIX} 组件初始化, open: ${open}`);

  const { t } = useTranslation('droid-android/android/components/content');

  // 监听 permissions 数组的变化
  const [permissions] = useProxyWatchUpdates(permissionsProps, 'permissions', permissionsProps.permissions);
  console.log(`${LOG_PREFIX} 当前已选权限数量: ${permissions.length}`);

  // 构造权限值到说明的映射 Map
  const permissionLabelMap = useMemo(() => {
    console.log(`${LOG_PREFIX} 开始构造权限标签映射`);
    const map = new Map<AndroidPermission, string>();

    // 处理 ManifestPermissionGroup
    const groupKeys = Object.keys(ManifestPermissionGroup) as (keyof typeof ManifestPermissionGroup)[];
    groupKeys.forEach(key => {
      const value = ManifestPermissionGroup[key] as AndroidPermission;
      const label = t(`Manifest.PermissionGroup.${key}`);
      map.set(value, label);
    });

    // 处理 ManifestPermission
    const permissionKeys = Object.keys(ManifestPermission) as (keyof typeof ManifestPermission)[];
    permissionKeys.forEach(key => {
      const value = ManifestPermission[key] as AndroidPermission;
      const label = t(`Manifest.Permission.${key}`);
      map.set(value, label);
    });

    console.log(`${LOG_PREFIX} 权限标签映射构造完成, 总数: ${map.size}`);
    return map;
  }, [t]);

  const handleClose = () => {
    console.log(`${LOG_PREFIX} 关闭按钮被点击`);
    onClose();
  };

  return (
    <Dialog
      open={open}
      onClose={handleClose}
      maxWidth="md"
      fullWidth
      sx={{
        '& .MuiDialog-paper': {
          minHeight: '60vh',
          maxHeight: '80vh',
        },
      }}
    >
      <DialogTitle sx={{ m: 0, p: 2, pr: 6 }}>
        {t('PermissionsSelector.Label', '选择 Android 权限')}
        <IconButton
          aria-label="close"
          onClick={handleClose}
          sx={{
            position: 'absolute',
            right: 8,
            top: 8,
            color: theme => theme.palette.grey[500],
          }}
        >
          <CloseIcon />
        </IconButton>
      </DialogTitle>
      <DialogContent dividers>
        {/* 已选权限显示区域 */}
        <Box sx={{ mb: 3, p: 2, bgcolor: '#f5f5f5', borderRadius: 1 }}>
          <Typography variant="subtitle2" sx={{ mb: 1.5, fontWeight: 'bold', color: 'primary.main' }}>
            {t('PermissionsSelector.SelectedPermissions', '已选权限')} ({permissions.length})
          </Typography>
          {permissions.length === 0 ? (
            <Typography variant="body2" color="text.secondary">
              {t('PermissionsSelector.NoPermissionsSelected', '未选择任何权限')}
            </Typography>
          ) : (
            <Stack direction="column" spacing={1.5}>
              {permissions.map((permission, index) => {
                const label = permissionLabelMap.get(permission);
                console.log(`${LOG_PREFIX} 渲染已选权限: ${permission}, 说明: ${label}`);

                return (
                  <Box
                    key={`${permission}-${index}`}
                    sx={{
                      p: 1.5,
                      bgcolor: 'white',
                      borderRadius: 1,
                      border: '1px solid',
                      borderColor: 'primary.light',
                    }}
                  >
                    <Typography variant="body2" sx={{ fontWeight: 500, color: 'primary.main', mb: 0.5 }}>
                      {label || permission}
                    </Typography>
                    <Typography variant="caption" color="text.secondary" sx={{ fontFamily: 'monospace' }}>
                      {permission}
                    </Typography>
                  </Box>
                );
              })}
            </Stack>
          )}
        </Box>

        {/* 分隔线 */}
        <Divider sx={{ mb: 2 }} />

        {/* 权限选择器 */}
        <AndroidPermissionsCheckbox {...permissionsProps} />
      </DialogContent>
    </Dialog>
  );
};
