import { AndroidPermission, ManifestPermission,  ManifestPermissionGroup} from '@droid/android';
import { useTranslation } from '@fanfanlo';
import { Autocomplete, Box, Chip, ListSubheader, TextField, Typography } from '@mui/material';
import { useMemo } from 'react';

// 定义用于 Autocomplete 的选项结构
interface PermissionOption {
  key: keyof typeof ManifestPermissionGroup | keyof typeof ManifestPermission;
  value: AndroidPermission;
  label: string; // 国际化后的权限说明
  group: 'ManifestPermissionGroup' | 'ManifestPermission';
}

interface IPermissionsProps {
  permissions: AndroidPermission[]; // 初始选中的权限值数组
}

/**
 * 权限选择器组件
 * @param props.permissions 初始选中的权限值数组
 */
export const 
AndroidPermissionsSelector: React.FC<IPermissionsProps> = ({ permissions }) => {
  const { t } = useTranslation('droid-android/android/components/content');

  // 1. 构造用于 Autocomplete 的完整选项列表 (options)
  const permissionOptions: PermissionOption[] = useMemo(() => {
    const options: PermissionOption[] = [];

    // 1.1. 处理 ManifestPermissionGroup
    (Object.keys(ManifestPermissionGroup) as (keyof typeof ManifestPermissionGroup)[]).forEach(key => {
      options.push({
        key: key,
        value: ManifestPermissionGroup[key] as AndroidPermission,
        label: t(`Manifest.PermissionGroup.${key}`),
        group: 'ManifestPermissionGroup',
      });
    });

    // 1.2. 处理 ManifestPermission
    (Object.keys(ManifestPermission) as (keyof typeof ManifestPermission)[]).forEach(key => {
      options.push({
        key: key,
        value: ManifestPermission[key] as AndroidPermission,
        label: t(`Manifest.Permission.${key}`),
        group: 'ManifestPermission',
      });
    });

    return options;
  }, [t]);

  // 2. 构造查询 Map (用于高效查找已选中的选项对象)
  const valueToOptionMap = useMemo(() => {
    const map = new Map<AndroidPermission, PermissionOption>();
    permissionOptions.forEach(option => {
      map.set(option.value, option);
    });
    return map;
  }, [permissionOptions]);

  // 3. 将传入的已选权限值数组 (permissions) 转换为 Autocomplete 需要的选项对象数组 (initialValue)
  const initialValue: PermissionOption[] = useMemo(() => {
    // 过滤掉那些在 Map 中找不到对应选项的无效权限值
    return permissions
      .map(p => valueToOptionMap.get(p))
      .filter((option): option is PermissionOption => option !== undefined);
  }, [permissions, valueToOptionMap]);

  return (
    <Autocomplete
      multiple
      // 设置 Autocomplete 的初始值
      // 注意：使用 defaultValue 使组件成为**非受控组件**，如果你希望在父组件中实时管理选择状态，
      // 应该使用 value 属性并结合外部状态管理（如 useState）。
      defaultValue={initialValue}
      // 选项来源
      options={permissionOptions}
      // 如何从 option 获取分组键
      groupBy={option => option.group}
      // 如何从 option 获取显示标签 (这是 Autocomplete 默认用于过滤和显示的属性)
      getOptionLabel={option => option.label}
      // **移除 onChange 逻辑，如你所要求**
      // onChange={(event, newValue) => { /* 外部逻辑处理 */ }}

      renderInput={params => (
        <TextField
          {...params}
          label={t('PermissionsSelector.Label', '选择 Android 权限')}
          placeholder={t('PermissionsSelector.Placeholder', '搜索权限')}
        />
      )}
      renderGroup={params => (
        <div key={params.key}>
          {/* 使用 ListSubheader 替代 Box，这更符合列表组件的语义 */}
          <ListSubheader component="div" sx={{ p: 1, backgroundColor: '#f5f5f5', lineHeight: 'normal' }}>
            <Typography variant="subtitle2" color="primary">
              {t(
                `PermissionsSelector.Group.${params.group}`,
                params.group === 'ManifestPermissionGroup' ? '权限组 (ManifestPermission Groups)' : '权限 (Permissions)',
              )}
            </Typography>
          </ListSubheader>
          {params.children}
        </div>
      )}
      // *** 核心修改点：renderTags 使用 option.label (国际化说明) ***
      // *** 修复后的 renderTags 部分 ***
      renderTags={(value, getTagProps) =>
        value.map((option: PermissionOption, index: number) => {
          // 提取 getTagProps 返回的所有属性
          const tagProps = getTagProps({ index });
          // 从 tagProps 中解构出 key，其余属性保存到 restProps
          const { key, ...restProps } = tagProps;

          return (
            <Chip
              key={key}
              {...restProps}
              label={option.label} // <-- 国际化说明
              sx={{ m: 0.5 }}
            />
          );
        })
      }
      sx={{ width: 500 }}
    />
  );
};
